// El unico flujo de n8n que decide algo, y esta es la razon:
//
// Todos los demas vigilantes le cuentan lo que ven a POST /vigilancia/estado, que aplica
// las reglas (tres sondeos seguidos, una llamada por averia, silencio de noche). Este no
// puede: el sujeto que vigila ES ese backend. Cuando esta caido, quien decide esta
// caido, asi que o decide este flujo o no se entera nadie.
//
// Por eso repite aqui las mismas tres reglas en pequeno, y por eso el contador vive en
// staticData: si viviera en memoria, cada ejecucion empezaria de cero y llamaria al
// primer parpadeo.

const UMBRAL = 3;
const s = $getWorkflowStaticData('global');
const j = $input.first().json;
const codigo = j.statusCode ?? 0;
const vivo = codigo >= 200 && codigo < 400;

if (vivo) {
  const estaba = s.fallos >= UMBRAL;
  s.fallos = 0; s.llamado = false;
  // Si nunca se llego a llamar, no hay nada que desdecir: silencio.
  return estaba ? [{ json: { llamar: false, volvio: true } }] : [];
}

s.fallos = (s.fallos || 0) + 1;
if (s.fallos < UMBRAL || s.llamado) return [];

// Franja nocturna, la misma que aplica el backend. Aqui escrita a mano porque el backend
// que la aplicaria es justo el que no contesta.
const hora = Number(new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid', hour: '2-digit', hour12: false }));
if (hora >= 0 && hora < 7) return [];

s.llamado = true;
const minutos = s.fallos * 5;
return [{ json: {
  llamar: true,
  message: 'Mikel, soy Jarvis. El backend lleva unos ' + minutos + ' minutos sin responder. Estoy mirando que pasa; dime y lo vemos.',
  context: 'Llamas tu porque el backend de Life Assistant no responde desde hace unos ' + minutos +
    ' minutos (' + s.fallos + ' sondeos seguidos fallidos). Codigo del ultimo intento: ' + (codigo || 'sin respuesta') +
    '. Ojo: este aviso NO viene del backend, viene del vigilante de n8n, precisamente porque el backend esta caido. ' +
    'Compruebalo tu mismo con el runbook de tu directorio de trabajo antes de proponer nada. ' +
    'Di primero que has encontrado, en una frase, y luego que harias. No actues sin que Mikel te lo confirme hablando.',
} }];
